import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth } from './helpers';

test.describe(`team member: mark my own tasks as done or edit them`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member marks their task as done, all teammates see the task move to the completed state within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      await loginViaHash(pageA, 0);
      await loginViaHash(pageB, 1);

      // Node 0 adds a task
      await pageA.getByTestId('field-title').fill('Task to complete');
      await pageA.getByTestId('action-add_task').click();
      const taskOnA = pageA.getByTestId('item-task').filter({ hasText: 'Task to complete' });
      await expect(taskOnA).toBeVisible({ timeout: 5_000 });

      // Node 0 toggles the task to done
      await taskOnA.getByTestId('action-toggle_task').click();

      // All teammates (node 1) see the task in the completed state within 5s
      const taskOnB = pageB.getByTestId('item-task').filter({ hasText: 'Task to complete' });
      await expect(taskOnB).toBeVisible({ timeout: 5_000 });
      // Task should carry the done indicator — data-done attribute set by the frontend
      // [Verifier] NOTE: asserting done via data-done="true" attribute on item-task
      await expect(taskOnB).toHaveAttribute('data-done', 'true', { timeout: 5_000 });
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test(`a member can only edit or complete tasks they authored; attempts on other members' tasks are rejected`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    try {
      // Node 1 creates a task (they are the author)
      await loginViaHash(pageB, 1);
      await pageB.getByTestId('field-title').fill('Node-1 authored task');
      await pageB.getByTestId('action-add_task').click();
      await expect(
        pageB.getByTestId('item-task').filter({ hasText: 'Node-1 authored task' })
      ).toBeVisible({ timeout: 5_000 });

      // Node 0 (a different member) sees the task
      await loginViaHash(pageA, 0);
      const foreignTask = pageA.getByTestId('item-task').filter({ hasText: 'Node-1 authored task' });
      await expect(foreignTask).toBeVisible({ timeout: 5_000 });

      // Toggle (complete) button should be disabled or absent for tasks node 0 did not author
      const toggleBtn = foreignTask.getByTestId('action-toggle_task');
      const toggleCount = await toggleBtn.count();
      if (toggleCount > 0) {
        await expect(toggleBtn).toBeDisabled();
      }

      // Edit button should also be disabled or absent
      const editBtn = foreignTask.getByTestId('action-edit_task');
      const editCount = await editBtn.count();
      if (editCount > 0) {
        await expect(editBtn).toBeDisabled();
      }
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });
});
